// HasRecipients applies the HasEdge predicate on the "recipients" edge.
func HasRecipients() predicate.MassEmailCampaign {
	return predicate.MassEmailCampaign(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RecipientsTable, RecipientsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRecipientsWith applies the HasEdge predicate on the "recipients" edge with a given conditions (other predicates).
func HasRecipientsWith(preds ...predicate.MassEmailRecipient) predicate.MassEmailCampaign {
	return predicate.MassEmailCampaign(func(s *sql.Selector) {
		step := newRecipientsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MassEmailCampaign) predicate.MassEmailCampaign {
	return predicate.MassEmailCampaign(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MassEmailCampaign) predicate.MassEmailCampaign {
	return predicate.MassEmailCampaign(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MassEmailCampaign) predicate.MassEmailCampaign {
	return predicate.MassEmailCampaign(sql.NotPredicates(p))
}
